import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../core/api_exception.dart';import '../core/session.dart';import '../models/entities.dart';import '../models/page_result.dart';import '../repositories/order_repository.dart';import '../widgets/page_frame.dart';import '../widgets/state_views.dart';
class MyOrdersScreen extends StatefulWidget{const MyOrdersScreen({super.key});@override State<MyOrdersScreen> createState()=>_S();}
class _S extends State<MyOrdersScreen>{PageResult<StoreOrder>? page;String? error;@override void initState(){super.initState();load();}Future<void> load()async{try{final r=await context.read<OrderRepository>().listForUser(context.read<Session>().userId!);if(mounted)setState((){page=r;error=null;});}on ApiException catch(e){if(mounted)setState(()=>error=e.message);}}@override Widget build(BuildContext context){if(page==null&&error==null)return const LoadingView();if(error!=null)return ErrorView(message:error!,onRetry:load);if(page!.items.isEmpty)return const EmptyView(message:'У вас пока нет заказов.');return PageFrame(maxWidth:900,child:ListView(children:[Text('Мои заказы',style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:14),for(final o in page!.items)Card(child:ListTile(leading:const Icon(Icons.receipt_long),title:Text('Заказ ${o.id}'),subtitle:Text('${o.status} · ${o.created}'),trailing:Text('${o.total.toStringAsFixed(2)} ₽')))]));}}
